from lib import Q
C='nail-intro-salon'
Q(C,'basic',"고대 이집트에서 손톱을 물들이는 데 쓴 식물성 염료는?","헤나",[("봉선화 기름","봉선화는 우리나라에서 손톱을 물들일 때 쓴 꽃입니다."),("아크릴 파우더","아크릴은 현대 인조 네일 재료입니다."),("아세톤","아세톤은 폴리시를 지우는 용제입니다.")],"고대 이집트 = 헤나로 손톱 물들임","고대 이집트에서는 **헤나**(식물에서 얻은 붉은 갈색 염료)로 손톱을 물들였고, 손톱 색으로 신분을 나타냈다고 전해집니다.",3,["네일 역사"])
Q(C,'basic',"우리나라에서 예로부터 여름에 손톱을 붉게 물들일 때 쓴 꽃은?","봉선화(봉숭아)",[("진달래","진달래는 화전 등 음식에 쓰였고 손톱 물들이기와는 관계가 없습니다."),("무궁화","무궁화는 나라꽃이며 손톱 물들이기에 쓰지 않았습니다."),("국화","국화는 차나 술에 쓰였습니다.")],"우리나라 전통 손톱 물들이기 = 봉선화","우리나라에서는 예로부터 **봉선화(봉숭아)** 꽃과 잎을 찧어 백반 등과 함께 손톱에 올려 붉게 물들였습니다.",3,["네일 역사"])
Q(C,'intermediate',"고대 이집트에서 손톱 색으로 신분을 나타낸 방법으로 알려진 것은?","신분이 높을수록 진한 붉은색을 칠했다",[("신분이 높을수록 흰색을 칠했다","흰색이 아니라 진한 붉은색이 높은 신분을 나타냈습니다."),("노예만 손톱에 색을 칠했다","오히려 신분이 낮은 사람은 옅은 색만 쓸 수 있었다고 전해집니다."),("왕족은 손톱을 칠하지 않았다","왕족이 가장 진한 색을 썼다고 전해집니다.")],"이집트: 신분 높을수록 진한 붉은색","고대 이집트에서는 **신분이 높을수록 진한 붉은색**, 신분이 낮을수록 옅은 색을 손톱에 칠했다고 전해집니다. 네일미용의 역사에서 자주 나오는 내용입니다.",3,["네일 역사"])
Q(C,'intermediate',"매니큐어(manicure)라는 말을 이루는 라틴어 'manus'가 뜻하는 것은?","손",[("발","발은 'pes(pedis)'로, 페디큐어(pedicure)의 어원입니다."),("관리","관리·손질은 'cura'의 뜻입니다."),("색","'manus'는 색과 관계가 없습니다.")],"매니큐어 = manus(손) + cura(관리)","**매니큐어**는 라틴어 **manus(손)**와 **cura(관리)**가 합쳐진 말로 '손 관리'를 뜻합니다. 발 관리인 페디큐어는 pes(발)와 cura에서 왔습니다.",3,["네일 용어"])
Q(C,'basic',"네일숍에서 리무버·아크릴 리퀴드 냄새와 파일 분진을 줄이는 가장 기본적인 방법은?","환기 장치를 갖추고 자주 환기한다",[("문과 창문을 늘 닫아 둔다","닫아 두면 냄새와 분진이 실내에 쌓입니다."),("향초를 피워 냄새를 덮는다","냄새를 가릴 뿐 해로운 증기와 분진은 그대로 남고, 불은 화재 위험도 있습니다."),("작업대 위에 제품 뚜껑을 열어 둔다","뚜껑을 열어 두면 증기가 더 많이 퍼집니다.")],"네일숍 공기 관리 = 환기","네일숍에서는 아세톤·아크릴 리퀴드 같은 화학 제품의 증기와 파일링 분진이 생기므로 **환기 장치를 갖추고 자주 환기**하는 것이 가장 기본입니다.",4,["네일숍 환경"])
Q(C,'basic',"아세톤·리무버 같은 인화성 제품의 보관 방법으로 가장 알맞은 것은?","뚜껑을 꼭 닫아 불기 없는 서늘한 곳에 둔다",[("햇볕이 잘 드는 창가에 둔다","열과 햇빛은 증발과 화재 위험을 키웁니다."),("뚜껑을 연 채 작업대에 둔다","증기가 퍼지고 쏟을 위험이 있습니다."),("난로 가까이에 두어 굳지 않게 한다","인화성 제품을 불 가까이 두면 매우 위험합니다.")],"인화성 제품 = 밀폐·서늘한 곳·화기 금지","아세톤과 리무버는 불이 잘 붙는 **인화성** 제품입니다. 뚜껑을 꼭 닫아 **불기가 없고 서늘한 곳**에 보관합니다.",4,["네일숍 안전"])
Q(C,'advanced',"네일숍의 전기 안전 수칙으로 옳지 않은 것은?","멀티탭 하나에 여러 기기의 플러그를 겹겹이 꽂아 쓴다",[("젖은 손으로 플러그를 만지지 않는다","옳은 수칙입니다. 감전을 막습니다."),("전선이 벗겨진 기기는 쓰지 않고 수리한다","옳은 수칙입니다."),("쓰지 않는 기기는 플러그를 뽑아 둔다","옳은 수칙입니다.")],"문어발식 멀티탭 = 과열·화재 위험","멀티탭 하나에 여러 기기를 겹겹이 꽂으면(문어발식) 전선이 **과열되어 화재**가 날 수 있습니다. 젖은 손으로 만지지 않기, 손상된 기기 쓰지 않기, 안 쓸 때 플러그 뽑기는 모두 맞는 안전 수칙입니다.",3,["네일숍 안전"],lock=True)
Q(C,'basic',"고객 관리 카드(상담 기록지)를 작성하는 목적으로 가장 알맞은 것은?","손발톱 상태·알레르기·시술 내용을 기록해 다음 시술과 사고 예방에 쓴다",[("고객에게 비싼 상품을 팔기 위해서","기록의 목적은 안전하고 알맞은 시술입니다."),("시술 시간을 늘리기 위해서","기록은 시술 시간을 늘리려는 것이 아닙니다."),("고객의 가족 정보를 모으기 위해서","시술과 관계없는 개인정보는 모으지 않습니다.")],"상담 기록 = 상태·알레르기·시술 내용 기록","고객 관리 카드에는 손발톱과 피부 상태, 알레르기·질환 여부, 시술 내용과 사용 제품을 적습니다. 다음 시술 계획을 세우고 **부작용·사고를 예방**하는 데 씁니다.",3,["고객응대"])
Q(C,'intermediate',"리무버가 묻은 솜과 거즈, 아크릴 잔여물을 버리는 방법으로 가장 알맞은 것은?","뚜껑이 있는 쓰레기통에 버리고 자주 비운다",[("작업대 위에 모아 두었다가 퇴근할 때 버린다","작업대에 두면 증기가 퍼지고 위생에도 나쁩니다."),("뚜껑 없는 바구니에 모아 둔다","뚜껑이 없으면 냄새와 증기가 퍼집니다."),("세면대 배수구에 흘려 버린다","화학 제품을 배수구에 버리면 안 됩니다.")],"화학 제품 묻은 쓰레기 = 뚜껑 있는 통, 자주 비움","화학 제품이 묻은 솜·거즈는 증기와 냄새가 나고 불이 붙을 수 있으므로 **뚜껑이 있는 쓰레기통**에 버리고 자주 비웁니다.",3,["네일숍 청결"])
Q(C,'basic',"네일미용의 뜻으로 가장 알맞은 것은?","손발톱과 그 주변 피부를 손질해 건강하고 아름답게 가꾸는 것",[("손발톱의 질병을 약으로 치료하는 것","질병 치료는 의료 행위이며 네일미용이 아닙니다."),("손등의 문신을 지우는 것","문신 제거는 네일미용이 아닙니다."),("머리카락을 자르고 염색하는 것","머리 손질은 미용사(일반)의 업무입니다.")],"네일미용 = 손발톱·주변 피부 손질과 화장","**네일미용**은 손톱·발톱과 그 주변 피부를 손질하고 꾸며 건강하고 아름답게 가꾸는 일입니다. 질병 치료는 하지 않습니다.",2,["네일미용 개념"])

C='nail-disorders-hygiene'
Q(C,'intermediate',"손발톱에 곰팡이가 감염되어 두꺼워지고 노랗게 변하며 잘 부스러지는 질환은?","조갑진균증(오니코마이코시스)",[("조갑종렬증(오니코렉시스)","손톱이 세로로 갈라지는 상태로 곰팡이 감염이 아닙니다."),("조백반증(루코니키아)","손톱의 흰 반점입니다."),("조갑익상편(테리지움)","큐티클이 손톱 위로 달라붙어 자라는 상태입니다.")],"곰팡이 감염 손발톱 = 오니코마이코시스(시술 금지)","**조갑진균증(오니코마이코시스)**은 손발톱의 곰팡이 감염입니다. 손발톱이 두꺼워지고 누렇게 변하며 부스러집니다. 옮을 수 있으므로 **시술하지 않고** 의사의 진료를 권합니다.",5,["네일 병변"])
Q(C,'basic',"손톱에 작은 하얀 반점이 생기는 것으로, 주로 가벼운 외상 때문에 생기며 시술이 가능한 상태는?","조백반증(루코니키아)",[("조갑주위염(파로니키아)","손톱 주위가 세균에 감염되어 붓는 질환으로 시술하면 안 됩니다."),("조갑진균증(오니코마이코시스)","곰팡이 감염으로 시술하면 안 됩니다."),("조갑박리증(오니코리시스)","손톱이 네일 베드에서 떨어지는 상태입니다.")],"흰 반점 = 루코니키아(시술 가능)","**조백반증(루코니키아)**은 손톱에 흰 반점이 생기는 것으로, 주로 손톱 뿌리 쪽에 가벼운 충격을 받아 생깁니다. 손톱이 자라면 없어지며 **시술이 가능**합니다.",4,["네일 병변"])
Q(C,'intermediate',"손톱이 세로로 갈라지거나 끝이 잘 부서지는 상태를 뜻하는 용어는?","조갑종렬증(오니코렉시스)",[("조내생증(오니코크립토시스)","손발톱이 살 속으로 파고드는 상태입니다."),("조백반증(루코니키아)","흰 반점이 생기는 상태입니다."),("거스러미(행네일)","손톱 주변 피부가 갈라져 일어나는 것입니다.")],"세로 갈라짐·부서짐 = 오니코렉시스","**조갑종렬증(오니코렉시스)**은 손톱이 세로로 갈라지고 잘 부서지는 상태입니다. 리무버를 지나치게 쓰거나 손톱이 건조할 때 생기기 쉬우며, 보습과 부드러운 관리로 돌봅니다.",3,["네일 병변"])
Q(C,'intermediate',"발톱이 살 속으로 파고들어 아프고 염증이 생기기 쉬운 상태(내향성 발톱)를 뜻하는 용어는?","조내생증(오니코크립토시스)",[("조갑종렬증(오니코렉시스)","세로로 갈라지는 상태입니다."),("조갑익상편(테리지움)","큐티클이 손톱 위로 달라붙어 자라는 상태입니다."),("조백반증(루코니키아)","흰 반점입니다.")],"파고드는 발톱 = 오니코크립토시스","**조내생증(오니코크립토시스)**은 발톱이 옆 살 속으로 파고드는 상태입니다. 꽉 끼는 신발, 발톱 양옆을 둥글고 깊게 깎는 습관이 원인이 됩니다. 염증이 있으면 시술하지 않고 진료를 권합니다.",4,["네일 병변"])
Q(C,'advanced',"내향성 발톱(오니코크립토시스)을 예방하는 발톱 손질 방법으로 가장 알맞은 것은?","발톱을 일자(스퀘어) 모양으로 너무 짧지 않게 자른다",[("발톱 양옆 모서리를 깊고 둥글게 깎는다","모서리를 깊게 깎으면 발톱이 살 속으로 파고들기 쉽습니다."),("발톱을 최대한 짧게 깎는다","너무 짧으면 살이 발톱 위로 올라와 파고들기 쉽습니다."),("발에 꼭 맞는 작은 신발을 신는다","꽉 끼는 신발은 원인이 됩니다.")],"내향성 발톱 예방 = 일자로, 너무 짧지 않게","발톱은 **일자(스퀘어)** 모양으로 끝이 발가락 끝과 비슷한 길이가 되게 자릅니다. 양옆을 깊게 둥글게 깎거나 너무 짧게 자르면 발톱이 살 속으로 파고들기 쉽습니다.",3,["네일 병변","페디큐어"])
Q(C,'intermediate',"큐티클이 지나치게 자라 네일 바디 위에 달라붙어 함께 자라는 상태는?","조갑익상편(테리지움)",[("조갑박리증(오니코리시스)","손톱이 네일 베드에서 떨어지는 상태입니다."),("조갑종렬증(오니코렉시스)","세로로 갈라지는 상태입니다."),("조갑진균증(오니코마이코시스)","곰팡이 감염입니다.")],"큐티클이 손톱 위에 달라붙어 자람 = 테리지움","**조갑익상편(테리지움)**은 큐티클이 지나치게 자라 네일 바디에 달라붙어 함께 앞으로 자라는 상태입니다. 억지로 떼어 내지 말고 보습하며 조심스럽게 관리합니다.",3,["네일 병변"])
Q(C,'basic',"손톱 주변 피부가 건조해 갈라지며 일어나는 거스러미(행네일)의 관리로 가장 알맞은 것은?","큐티클 오일로 보습하고 일어난 부분만 니퍼로 조심해 자른다",[("손으로 잡아 뜯어낸다","뜯으면 상처가 커지고 감염될 수 있습니다."),("리무버를 자주 발라 말린다","리무버는 피부를 더 건조하게 만듭니다."),("그대로 두고 파일로 문지른다","파일로 문지르면 피부가 더 상합니다.")],"거스러미 = 보습 + 니퍼로 조심해 정리","**거스러미(행네일)**는 손톱 주변 피부가 건조해 갈라진 것입니다. 손으로 뜯지 말고 **큐티클 오일로 보습**한 뒤 일어난 부분만 소독한 니퍼로 조심스럽게 잘라 냅니다.",4,["네일 병변"])
Q(C,'intermediate',"손톱 주위가 세균에 감염되어 붉게 붓고 고름이 생기는 질환은?","조갑주위염(파로니키아)",[("조백반증(루코니키아)","흰 반점으로 감염이 아닙니다."),("조갑익상편(테리지움)","큐티클이 손톱 위로 자라는 상태입니다."),("조갑종렬증(오니코렉시스)","세로로 갈라지는 상태입니다.")],"손톱 주위 세균 감염 = 파로니키아(시술 금지)","**조갑주위염(파로니키아)**은 손톱 주위 피부가 세균에 감염되어 붉게 붓고 고름이 생기는 질환입니다. **시술하지 않고** 의사의 진료를 권합니다.",4,["네일 병변"])
Q(C,'advanced',"손톱이 네일 베드(조상)에서 떨어져 들뜨고, 떨어진 부분이 하얗게 보이는 상태는?","조갑박리증(오니코리시스)",[("조갑익상편(테리지움)","큐티클이 손톱 위로 달라붙어 자라는 상태입니다."),("조내생증(오니코크립토시스)","손발톱이 살로 파고드는 상태입니다."),("조백반증(루코니키아)","손톱 속 작은 흰 반점으로, 손톱이 떨어진 것이 아닙니다.")],"손톱이 네일 베드에서 떨어짐 = 오니코리시스","**조갑박리증(오니코리시스)**은 손톱이 아래의 네일 베드에서 떨어져 들뜨는 상태로, 떨어진 부분은 하얗게 보입니다. 원인이 감염일 수 있으므로 시술하지 않고 진료를 권합니다.",3,["네일 병변"])
Q(C,'basic',"네일 작업자의 개인위생 관리로 옳지 않은 것은?","손에 상처가 있어도 장갑 없이 그대로 시술한다",[("시술 전후에 손을 씻고 소독한다","옳은 위생 관리입니다."),("깨끗한 작업복을 입는다","옳은 위생 관리입니다."),("필요하면 마스크를 써서 분진을 막는다","옳은 위생 관리입니다.")],"작업자 손 상처 = 장갑 착용","작업자는 시술 전후 손 씻기와 손 소독, 깨끗한 작업복, 분진을 막는 마스크를 갖춥니다. **손에 상처가 있으면 장갑을 껴서** 감염을 막아야 합니다.",3,["개인위생"],lock=True)
Q(C,'basic',"네일 시술을 시작하기 전 고객의 손에 대한 위생 처리로 가장 알맞은 것은?","고객의 손을 씻게 하거나 손 소독제로 소독한다",[("고객의 손에 큐티클 오일을 먼저 바른다","오일은 위생 처리가 아니며 유분이 남습니다."),("고객의 손에 핸드크림을 듬뿍 바른다","위생 처리가 아니고 유분이 남아 시술에 방해가 됩니다."),("아무 처리 없이 바로 파일링한다","위생 처리를 먼저 해야 합니다.")],"시술 전 고객 손 소독","시술 전에는 작업자와 마찬가지로 **고객의 손도 씻거나 소독제로 소독**해 세균 감염을 막습니다.",3,["고객 위생"])
